      "theory": "\n            <h4>1. Волшебство Auto Layout в Figma</h4>\n            <p>Раньше, если текст на кнопке менялся с «Ок» на «Зарегистрироваться на курс», дизайнеру приходилось вручную растягивать синий прямоугольник.\n            С функцией <strong>Auto Layout (Shift + A)</strong> кнопка ведёт себя как живая: вы просто пишете текст, а рамка кнопки сама расширяется, сохраняя идеальные отступы по краям!</p>\n            <h4>2. Главные настройки Auto Layout</h4>\n            <p>- <strong>Padding (внутренние отступы)</strong>: например, 12 px сверху/снизу и 24 px слева/справа;\n            - <strong>Gap (расстояние между элементами)</strong>: зазор между иконкой и текстом кнопки (например, 8 px);\n            - <strong>Corner Radius</strong>: скругление углов (например, 12 px для красивых мягких кнопок).</p>\n        ",
