      "theory": "\n            <h4>1. Зачем нужны компоненты в веб-дизайне?</h4>\n            <p>Представьте, что на сайте 50 страниц, и на каждой есть кнопка. Если заказчик попросит сделать кнопку фиолетовой вместо синей, перекрашивать 50 кнопок вручную — долго и скучно.\n            В Figma мы выделяем кнопку и делаем её <strong>Компонентом (Component)</strong>. Теперь эта кнопка — главная («мама»). Все остальные кнопки на страницах становятся её копиями (<strong>Instances</strong>). Меняем цвет в главной кнопке — он мгновенно меняется на всех 50 страницах!</p>\n            <h4>2. Варианты кнопки: обычная (Default) и при наведении (Hover)</h4>\n            <p>В панели <strong>Variants</strong> мы добавляем второе состояние кнопки: при наведении мышки цвет становится чуть темнее (например, #4338CA), чтобы пользователь понимал, что кнопка кликабельна.</p>\n        ",
