      "theory": "\n            <h4>1. CSS — это оформление и красота нашего макета</h4>\n            <p>Если HTML — это кирпичи дома, то CSS — это покраска стен, красивые обои и мягкие ковры.\n            В CSS мы пишем простые и понятные правила:\n            - <code>color: #0f172a;</code> — цвет текста;\n            - <code>background: #ffffff;</code> — цвет фона;\n            - <code>border-radius: 16px;</code> — те самые скругления углов, которые мы настраивали в Figma!\n            - <code>padding: 24px;</code> — внутренний отступ, чтобы тексту внутри карточки не было тесно.</p>\n            <h4>2. Разница между Padding и Margin</h4>\n            <p><strong>Padding</strong> — отступ <em>внутри</em> карточки (воздух до рамки).\n            <strong>Margin</strong> — отступ <em>снаружи</em> карточки (расстояние до соседних карточек).</p>\n        ",
