      "time_limit": "60 мин",
      "tools": "CSS Flexbox, display: flex, justify-content: space-between, align-items: center",
      "summary": "Напишите CSS-стили для шапки сайта .header: включите режим display: flex, разнесите логотип и навигацию по краям через justify-content: space-between и отцентрируйте по вертикали через align-items: center.",
      "theory": "\n            <h4>1. Как расположить элементы в один ряд?</h4>\n            <p>По умолчанию все теги в браузере падают друг под друга столбиком. Но в шапке сайта нам нужно, чтобы <strong>логотип был слева, а меню и кнопка — справа</strong>!\n            Для этого в CSS придумали супер-удобный инструмент — <strong>Flexbox</strong>. Достаточно написать всего одну строчку родительскому контейнеру: <code>display: flex;</code> — и все дети мгновенно встанут в ровную красивую строку!</p>\n            <h4>2. Главные команды Flexbox для шапки</h4>\n            <p>- <code>display: flex;</code> — включает режим гибкого ряда;\n            - <code>justify-content: space-between;</code> — расталкивает логотип в самый левый край, а меню в правый;\n            - <code>align-items: center;</code> — идеально выравнивает элементы по вертикальному центру строки.</p>\n        ",
