      "theory": "\n            <h4>1. Как оживить кнопку без сложного программирования</h4>\n            <p>Веб-дизайнеру достаточно понимать самый простой базовый принцип: как сделать так, чтобы при клике пользователя на кнопку происходило действие.\n            Всё состоит всего из трёх простых шагов:\n            1. Находим кнопку на странице: <code>const btn = document.querySelector('button');</code>\n            2. Говорим браузеру «слушай клик»: <code>btn.addEventListener('click', function() { ... });</code>\n            3. Внутри пишем простое действие: например, показать вежливое сообщение <code>alert('Спасибо за заявку!');</code> или сменить текст кнопки.</p>\n        ",
