      "theory": "\n            <h4>1. Финал курса: от дизайна в Figma к готовой веб-карточке!</h4>\n            <p>Вы прошли путь от подготовки графики в Photoshop и векторных иконок в Illustrator до создания макетов в Figma и базовой верстки.\n            В итоговом проекте вы собираете аккуратную карточку продукта:\n            - HTML-разметка с картинкой, заголовком, текстом и кнопкой;\n            - CSS-стили: отступы, скругления углов 16px, мягкая тень и интерактивный эффект при наведении мыши (<code>:hover</code>).</p>\n        ",
