      "theory": "\n            <h4>1. Композиционный центр и правило третей</h4>\n            <p>В графическом дизайне взгляд зрителя управляется через <strong>доминанту (фокусную точку)</strong>, контраст масштабов и воздух (негативное пространство). При делении макета сеткой <code>3×3</code> ключевые акценты размещаются на пересечениях силовых линий.</p>\n            <h4>2. Гештальт-принцип близости и внутреннего/внешнего</h4>\n            <p>Объекты, расположенные близко друг к другу, воспринимаются как единая смысловая группа. Внутренние отступы внутри блока всегда должны быть меньше внешних полей вокруг него.</p>\n        ",
