      "theory": "\n            <h4>1. Математическая природа вектора и кривые Безье</h4>\n            <p>В отличие от пиксельного растра, векторная графика строится опорными узлами (Anchor Points) и направляющими рычагами кривых Безье — поэтому логотип масштабируется от фавиконки <code>16px</code> до билборда <code>6×3 м</code> без малейшей потери резкости.</p>\n            <h4>2. Чистота контура и Pathfinder</h4>\n            <p>Профессиональный знак содержит минимум опорных точек (узлы ставятся только в экстремумах кривой — верх, низ, лево, право). Все обводки перед сдачей в печать переводятся в кривые (<code>Expand / Outline Stroke</code>), а пересечения объединяются через <strong>Pathfinder (Unite, Minus Front)</strong>.</p>\n        ",
