      "theory": "\n            <h4>1. Автоматизация многостраничных изданий</h4>\n            <p>Вёрстка книг, журналов и корпоративных отчётов выполняется в <strong>Adobe InDesign</strong>. Повторяющиеся элементы (колонцифры с автонумерацией, колонтитулы, направляющие колонок) выносятся на <strong>Parent / Master Pages</strong>.</p>\n            <h4>2. Привязка к сетке базовых линий и стили</h4>\n            <p>Строгая привязка текста к <code>Baseline Grid</code> гарантирует совпадение строк на левой и правой полосах разворота и на просвет бумаги. Форматирование выполняется строго через <strong>Paragraph Styles</strong> и <strong>Character Styles</strong>, а висячие предлоги и одинокие строки («вдовы» и «сироты») устраняются настройками <code>Keep Options</code> и GREP.</p>\n        ",
