      "theory": "\n            <h4>1. Неразрушающее редактирование (Non-Destructive Workflow)</h4>\n            <p>Профессиональный ретушёр никогда не стирает пиксели ластиком на исходном слое. Вместо этого применяются <strong>маски слоёв (Layer Masks)</strong>, корректирующие слои (<code>Curves</code>, <code>Hue/Saturation</code>, <code>Selective Color</code>) и <strong>Smart Objects</strong>, сохраняющие исходное качество растра при трансформации.</p>\n            <h4>2. Частотное разложение и обтравка пером</h4>\n            <p>Для предметной и портретной ретуши изображение разделяют на низкую частоту (светотеневой объём и цвет) и высокую частоту (текстура поверхности), сохраняя естественную фактуру без эффекта «пластиковой кожи».</p>\n        ",
