      "theory": "\n            <h4>1. Золотой чек-лист сдачи тиража в печать</h4>\n            <p>Любая ошибка на этапе допечатной подготовки стоит перепечатки всего тиража. Гильотина в типографии имеет погрешность реза до <code>1–2 мм</code>, поэтому все фоновые плашки и фото выпускаются за обрезной формат минимум на <strong>3 мм (Bleeds)</strong>, а важные тексты отодвигаются внутрь от реза минимум на <strong>4–5 мм</strong>.</p>\n            <h4>2. Разрешение, шрифты и PDF/X</h4>\n            <p>Эффективное разрешение растровых иллюстраций для листовой печати — строго <code>300 dpi</code> в масштабе 100%, цветовая модель <code>CMYK</code>, отсутствие случайного белого Overprint и экспорт в промышленный стандарт <strong>PDF/X-1a</strong> или <strong>PDF/X-4</strong>.</p>\n        ",
