      "theory": "\n            <h4>1. Презентация проекта на фотореалистичных мокапах (Mockups)</h4>\n            <p>Заказчик оценивает бренд не по плоским схемам, а по тому, как он живёт в реальной среде: на текстурной бумаге визитки, вывеске, стаканчике кофе и экране смартфона. В Adobe Photoshop макет помещается внутрь <strong>Smart Object (Смарт-объекта)</strong> с режимами наложения <code>Multiply / Linear Burn</code> и картами смещения (<em>Displacement Map</em>), сохраняя естественные светотени и фактуру материала.</p>\n            <h4>2. Структура выпускного архива (Hand-off Package)</h4>\n            <p>Профессиональный графический дизайнер передаёт клиенту упорядоченный релиз-пакет: папку <code>01_Logo</code> (AI, EPS, SVG, PNG), <code>02_Print_Prepress</code> (файлы <strong>PDF/X</strong> в <strong>CMYK / Pantone</strong> с вылетами 3 мм) и <code>03_Brandbook_Presentation</code> (интерактивный гайдлайн и превью на мокапах).</p>\n        ",
