      "theory": "\n            <h4>1. Закон Ома и мощность в бортовой сети 12В / 24В</h4>\n            <p>Сила тока в автомобильной цепи вычисляется по формуле <code>I = P / U</code>. Например, две галогенные лампы дальнего света общей мощностью <code>120 Вт</code> при напряжении <code>12 В</code> потребляют ток <code>I = 120 / 12 = 10 А</code>. Сечение медного провода выбирают с запасом по нагреву и допустимой потере напряжения, а предохранитель ставят в максимальной близости от плюсовой клеммы АКБ для защиты самого провода от возгорания.</p>\n            <h4>2. Диагностика методом падения напряжения (Voltage Drop)</h4>\n            <p>Обычная прозвонка омметром без нагрузки часто показывает «0.2 Ом» даже на сгнившем проводе, где осталась одна жилка! Замер вольтметром параллельно участку цепи <strong>под рабочей нагрузкой</strong> сразу выявляет окисленный контакт: падение на участке силовой массы или плюса свыше <code>0.2–0.5 В</code> требует зачистки или обжима клеммы.</p>\n        ",
