      "theory": "\n            <h4>1. Физический уровень высокоскоростной шины CAN (500 кбит/с)</h4>\n            <p>Блоки управления двигателя, АКПП, ABS/ESP и приборной панели общаются по дифференциальной витой паре: <strong>CAN-High</strong> (доминантный импульс вверх: <code>2.5 В → 3.5 В</code>) и <strong>CAN-Low</strong> (зеркальный импульс вниз: <code>2.5 В → 1.5 В</code>). На двух дальних концах магистрали установлены согласующие резисторы-терминаторы по <code>120 Ом</code> каждый.</p>\n            <h4>2. Проверка сопротивления терминаторов (60 Ом)</h4>\n            <p>При полностью <strong>снятой клемме АКБ</strong> сопротивление между пинами <strong>6 (CAN-H)</strong> и <strong>14 (CAN-L)</strong> разъёма OBD-II обязано составлять <strong>60 Ом</strong> (два резистора по 120 Ом включены параллельно: <code>120 / 2 = 60 Ом</code>). Показание <code>120 Ом</code> сразу указывает на обрыв магистрали до одного из терминальных блоков, а <code>0–2 Ом</code> — на короткое замыкание проводов витой пары между собой!</p>\n        ",
