      "theory": "\n            <h4>1. Алгоритм комплексной аттестационной диагностики (WorldSkills / ТиПО)</h4>\n            <p>На квалификационном экзамене по специальности <code>07161301 — Автоэлектрики</code> выпускник проводит полную инструментальную инспекцию автомобиля по 4 контурам без угадывания и хаотичной замены деталей:\n            1. <strong>Энергобаланс и силовые цепи</strong>: ЭДС покоя АКБ (<code>12.6–12.7 В</code>), ток утечки (<code>≤ 30–50 мА</code>), падение напряжения на стартере (<code>≤ 0.5 В</code>) и зарядка генератора под нагрузкой (<code>13.8–14.4 В</code>).\n            2. <strong>Сетевая архитектура</strong>: сопротивление терминаторов шины CAN (<code>60 Ом</code>) и симметрия дифференциальных сигналов <code>CAN-High / CAN-Low</code>.\n            3. <strong>Системы управления ДВС и кузовом</strong>: чтение кодов DTC, анализ Freeze Frame и эталонная осциллограмма синхронизации <code>ДПКВ + ДПРВ</code>.\n            4. <strong>Итоговое экспертное заключение</strong> с перечнем выявленных дефектов и проверочных измерений после ремонта.</p>\n        ",
