      "theory": "\n            <h4>1. Современные хладагенты и техника безопасности</h4>\n            <p><strong>R600a (Изобутан)</strong> и <strong>R290 (Пропан)</strong> — природные углеводородные газы, используемые в бытовых холодильниках. Они взрывопожароопасны: пайка на контуре с R600a допускается <em>только после полной эвакуации фреона или с применением безгаечных соединений Lokring</em>!\n            <strong>R134a</strong> (тетрафторэтан) — негорючий HFC-хладагент, применяется в автокондиционерах и среднетемпературных витринах. \n            <strong>R404A</strong> / <strong>R452A</strong> — зеотропные смеси для низкотемпературного коммерческого холода.</p>\n            <h4>2. Совместимость с маслами</h4>\n            <p>Фреон R134a и R404A работают исключительно с <strong>полиолэфирными синтетическими маслами (POE)</strong>. Масла POE гигроскопичны (активно впитывают влагу из воздуха), поэтому время открытого контура не должно превышать 15 минут! Минеральные масла применяются с хлорсодержащими фреонами и изобутаном R600a.</p>\n        ",
