      "theory": "\n            <h4>1. Медно-фосфорные и серебряные припои</h4>\n            <p><strong>Медь + медь</strong> паяется медно-фосфорным припоем (с содержанием фосфора <code>5–7%</code>, например CuP6 или с добавлением 2–5% серебра). Фосфор сам работает как флюс, восстанавливая оксиды меди — дополнительный флюс не требуется.\n            <strong>Медь + сталь</strong> (пайка патрубка компрессора или конденсатора) паяется исключительно <strong>серебряным припоем (30–45% Ag)</strong> со специальным пастообразным флюсом (бура/флюс для серебра).</p>\n            <h4>2. Продувка сухим азотом при пайке</h4>\n            <p>При нагреве медной трубы горелкой до температуры <code>700–800 °C</code> внутри неё без азота образуется толстая чёрная окалина (оксид меди CuO). При пуске фреона эта окалина смывается маслом и <em>намертво забивает капиллярную трубку</em>! Профессионалы подают сквозь трубу слабый ток сухого азота (давление <code>0.1–0.2 бар</code>), защищая внутреннюю полость от окисления.</p>\n        ",
