      "theory": "\n            <h4>1. Точная дозировка по заводскому шильдику (Nameplate)</h4>\n            <p>В холодильниках с капиллярной трубкой <strong>нет ресивера жидкого хладагента</strong>, поэтому ошибка заправки даже на <code>±5–10 грамм</code> критична!\n            При <strong>перезаправке</strong>: хладагент не помещается в испарителе, конденсация растёт, всасывающая трубка обмерзает «шубой» до самого компрессора, падает холодопроизводительность.\n            При <strong>недозаправке</strong>: испаритель обмерзает лишь частично, компрессор работает без остановки, перегреваясь.</p>\n            <h4>2. Технология заправки жидкой и газовой фазой</h4>\n            <p><strong>R600a</strong> и <strong>R134a</strong> можно подавать парами (баллон вентилем вверх) на работающем компрессоре или дозированно в жидкой фазе на остановленный вакуумированный контур.\n            <strong>R404A</strong> (смесевой хладагент) заправляют <strong>строго в жидкой фазе (баллон вентилем вниз)</strong>, иначе нарушится процентный состав фракций смеси!</p>\n        ",
