      "theory": "\n            <h4>1. Принцип работы автоматической системы No Frost</h4>\n            <p>В холодильниках No Frost испаритель спрятан за пластиковой панелью и продувается вентилятором. Чтобы ребра испарителя не зарастали шубой инея, каждые <code>6–12 часов</code> работы компрессора таймер оттайки отключает компрессор и включает <strong>электрический ТЭН оттайки</strong> (мощностью <code>120–250 Вт</code>).</p>\n            <h4>2. Защитная цепочка разморозки</h4>\n            <p><strong>Биметаллический дефрост-термостат (клипса на испарителе)</strong>: замкнут только при отрицательной температуре (<code>ниже -5 °C</code>). Как только весь лед растаял и испаритель нагрелся до <code>+8...+10 °C</code>, биметалл размыкает цепь ТЭНа, не давая греть морозилку.\n            <strong>Термоплавкий предохранитель (Thermal Fuse)</strong>: включён последовательно с ТЭНом на случай залипания реле. Перегорает при аварийных <code>+72...+84 °C</code>, спасая пластиковый шкаф от пожара.</p>\n        ",
