      "theory": "\n            <h4>1. Отличие инверторного компрессора BLDC от линейного (On/Off)</h4>\n            <p>В современных холодильниках и сплит-системах применяются трёхфазные бесколлекторные компрессоры с постоянными магнитами (<strong>BLDC — Brushless DC</strong>). В отличие от обычного компрессора 220 В с пусковым реле, инверторный мотор питается от <strong>платы частотного преобразователя (Инвертора)</strong> переменным трёхфазным напряжением с изменяемой частотой (от <code>40 Гц</code> до <code>150 Гц</code>), плавно регулируя холодопроизводительность без пусковых бросков тока.</p>\n            <h4>2. Методика раздельной диагностики: Плата инвертора vs Компрессор</h4>\n            <p>1. <strong>Проверка обмоток компрессора (U, V, W)</strong>: в трёхфазном инверторном компрессоре сопротивления между всеми тремя парами штырей (<code>U–V</code>, <code>V–W</code>, <code>U–W</code>) обязаны быть <strong>строго одинаковыми</strong> (например, по <code>9.5 Ом ± 2%</code>), а пробой на корпус отсутствует.\n            2. <strong>Проверка сигнала управления ШИМ (PWM)</strong>: основная плата управления подаёт на плату инвертора низковольтный импульсный сигнал (или UART) для задания оборотов. Светодиодная индикация ошибки на плате инвертора (коды миганий) позволяет точно определить причину остановки: срыв старта ротора, перегрузка по току IPM-модуля или потеря связи.</p>\n        ",
