      "theory": "\n            <h4>1. Регламент приёмо-сдаточных испытаний холодильной установки</h4>\n            <p>На квалификационном экзамене по специальности <code>07130700 — Ремонт холодильного оборудования</code> выпускник выполняет полный цикл пусконаладки и заполняет официальный <strong>Технический паспорт готовности холодильного оборудования (ГТО)</strong>:\n            1. <strong>Испытание на прочность и плотность</strong>: опрессовка сухим азотом (выдержка под давлением без падения по манометру).\n            2. <strong>Глубокое вакуумирование</strong>: достижение остаточного давления ниже <code>500 микрон</code> с тестом на удержание вакуума.\n            3. <strong>Заправка и термодинамическая настройка</strong>: заправка расчётной массы хладагента по весам, вывод камеры на уставку температуры и контроль рабочего <strong>перегрева (Superheat <code>6–8 K</code>)</strong> и <strong>переохлаждения (Subcooling <code>4–6 K</code>)</strong>.\n            4. <strong>Проверка защитной автоматики</strong>: срабатывание реле высокого/низкого давления (РД), циклов оттайки и выдача <strong>допуска в эксплуатацию</strong>.</p>\n        ",
