      "theory": "\n            <h4>1. Синхронизация меток ГРМ и фазы</h4>\n            <p>Коленчатый вал делает <strong>два оборота (720°)</strong> за один оборот распределительного вала (360°). При замене ремня или цепи ГРМ 1-й цилиндр устанавливается в ВМТ такта сжатия. Ошибочный сдвиг даже на <code>1–2 зуба</code> приводит к падению тяги, рассинхронизации фаз (DTC P0016), а на двигателях «интерференционного» типа — к <strong>загибу клапанов о поршни</strong>!</p>\n            <h4>2. Тепловой зазор клапанов</h4>\n            <p>Металл клапана удлиняется при нагреве. Тепловой зазор компенсирует расширение стержня.\n            Норма зазоров на холодном моторе (20 °C):\n            - Впускные клапаны: <strong>0.15–0.25 мм</strong>;\n            - Выпускные клапаны (нагреваются горячими газами сильнее): <strong>0.25–0.35 мм</strong>.\n            Зажатый клапан (зазор 0.05 мм) не садится плотно на седло, перегревается и прогорает; чрезмерный зазор (0.50 мм) вызывает цокот и ударный износ кулачков распредвала.</p>\n        ",
