      "theory": "\n            <h4>1. Признаки и дефектовка узла сцепления</h4>\n            <p>- <strong>Сцепление «буксует»</strong> (обороты мотора растут, машина не ускоряется): износ фрикционных накладок ведомого диска до заклепок (толщина менее <code>1.5–1.6 мм</code> над головкой заклепки), замасливание накладок через задний сальник коленвала;\n            - <strong>Сцепление «ведёт»</strong> (не выключается до конца, передачи включаются с хрустом): деформация диафрагменной пружины корзины, коробление диска (осевое биение более <code>0.5 мм</code>);\n            - <strong>Шум/гул при нажатии на педаль</strong>: износ и люфт выжимного подшипника.</p>\n            <h4>2. Правило центровки диска</h4>\n            <p>Перед окончательной затяжкой болтов корзины ведомый диск <strong>обязательно центруется первичным валом или ступенчатой оправкой</strong> по подшипнику в торце коленвала. Если диск смещён хотя бы на 1 мм, первичный вал КПП невозможно завести в шлицы при установке коробки передач!</p>\n        ",
