      "theory": "\n            <h4>1. Три ключевых геометрических угла подвески</h4>\n            <p>Перед регулировкой обязателен <strong>Run-out (компенсация биения колес прокатыванием)</strong> и проверка давления в шинах.\n            - <strong>Развал (Camber)</strong>: наклон колеса относительно вертикали при виде спереди. Отрицательный развал (колеса домиком <code>/ \\</code>) улучшает зацеп в повороте; избыточный развал «жрёт» внутренний или наружный край протектора;\n            - <strong>Кастор (Caster)</strong>: продольный наклон оси поворота колеса. Обеспечивает прямолинейную стабильность на скорости и <strong>самовозврат руля в нейтраль</strong> при выходе из поворота;\n            - <strong>Схождение (Toe)</strong>: разница расстояний между передними и задними кромками шин на одной оси. Самый чувствительный угол: ошибка схождения всего в <code>+15' (минут)</code> стирает шину в ноль за пару тысяч километров «пилообразным» износом!</p>\n            <h4>2. Очередность регулировки</h4>\n            <p>Регулировка выполняется строго по цепочке: <strong>Задняя ось (Развал → Схождение) → Передняя ось (Кастор → Развал → Схождение)</strong> с контролем центрального положения спицы рулевого колеса.</p>\n        ",
