      "theory": "\n            <h4>1. Статический и динамический дисбаланс колеса</h4>\n            <p>Дисбаланс колеса массой всего <code>15–20 грамм</code> на скорости <code>100 км/ч</code> превращается в центробежную ударную силу свыше <code>3–5 кг</code>, разбивающую ступичный подшипник, рулевые наконечники и вызывающую биение руля.\n            - <strong>Статический дисбаланс</strong> («подпрыгивание» колеса вверх-вниз) — устраняется установкой грузов в противовес тяжёлой точке;\n            - <strong>Динамический дисбаланс</strong> («шимми» / виляние колеса влево-вправо по оси вращения) — устраняется раздельной установкой балансировочных грузов на внутреннюю и наружную закраины обода диска.</p>\n            <h4>2. Момент затяжки колесного крепежа</h4>\n            <p>Затягивать колесные болты и гайки пневмогайковёртом «намертво» без контроля — грубейший непрофессионализм! Это вытягивает резьбу, деформирует тормозной диск и делает невозможным откручивание колеса штатным баллонным ключом в дороге. Финальная протяжка выполняется <strong>строго динамометрическим ключом крест-накрест моментом 110–140 Н·м</strong> (согласно мануалу марки).</p>\n        ",
