      "theory": "\n            <h4>1. Регламенты ТО-1 и ТО-2</h4>\n            <p>Периодическое ТО — основа надёжности и ресурса автомобиля.\n            <strong>ТО-1 (каждые 10 000–15 000 км / 1 год)</strong>: замена моторного масла с масляным фильтром, замена воздушного и салонного фильтров, осмотр подвески, проверка колодок/дисков, уровня технических жидкостей (тормозная, охлаждающая, ГУР) и давления в шинах.\n            <strong>ТО-2 (каждые 30 000–60 000 км)</strong>: дополнительно включает замену свечей зажигания, тормозной жидкости, антифриза, масла в МКПП/АКПП, ремня навесных агрегатов и ремня/цепи ГРМ.</p>\n            <h4>2. Правила сдачи автомобиля клиенту (Заказ-наряд)</h4>\n            <p>Профессиональный автомеханик оформляет <strong>официальный заказ-наряд</strong> с перечнем проверенных систем по чек-листу, остаточными ресурсами расходников (толщина колодок в мм, плотность антифриза, остаток протектора шин в мм), номерами установленных деталей и рекомендациями для следующего заезда.</p>\n        ",
