      "theory": "\n            <h4>1. Диагностика рулевой рейки, рулевых тяг и наконечников</h4>\n            <p>Рулевое управление напрямую отвечает за жизнь водителя и пассажиров. При покачивании руля помощником мастер на подъёмнике проверяет:\n            - <strong>Рулевые наконечники</strong>: любой ощутимый радиальный или осевой люфт в шаровом пальце, а также разрыв резинового пыльника требуют немедленной замены детали;\n            - <strong>Внутренние рулевые тяги («яблоки»)</strong>: проверяются на осевой стук в шарнире под гофрированным кожухом рейки;\n            - <strong>Рулевая рейка (ГУР / ЭУР)</strong>: оценивается износ опорной втулки горизонтального штока, отсутствие течи рабочей жидкости ATF/PSF через сальники ГУР и состояние зубчатого зацепления «шестерня — рейка».</p>\n            <h4>2. Правила замены и обязательный контроль схождения</h4>\n            <p>Выпрессовка пальца рулевого наконечника из поворотного кулака выполняется <strong>только специальным винтовым съёмником</strong> (удары кувалдой по уху чугунного или алюминиевого кулака деформируют посадочный конус!). Гайка пальца затягивается динамометрическим ключом строго по моменту завода. После любого вмешательства в рулевые тяги или наконечники <strong>регулировка схождения колёс на 3D-стенде обязательна</strong>!</p>\n        ",
