      "theory": "\n            <h4>1. Выпускной контроль качества (ОТК) в дилерском сервисном центре</h4>\n            <p>На квалификационной защите по специальности <code>07161300 — Автомеханики</code> выпускник выступает в роли мастера-приёмщика и инженера ОТК. Ни один автомобиль не выдаётся клиенту без заполнения <strong>Карты итогового инструментального контроля ОТК</strong> по 4 критическим узлам безопасности:\n            1. <strong>Силовой агрегат (ДВС)</strong>: ровная компрессия по цилиндрам (разброс <code>≤ 1.0 бар</code>), номинальное давление масла, отсутствие течей технических жидкостей и совпадение фаз ГРМ.\n            2. <strong>Тормозная система</strong>: остаточная толщина дисков (выше <code>Min TH</code>), биение <code>≤ 0.05 мм</code>, температура кипения жидкости DOT 4 (<code>> 200 °C</code>) и равномерность тормозных усилий по осям.\n            3. <strong>Рулевое управление и ходовая часть</strong>: отсутствие люфтов в шаровых опорах и рулевых тягах, распечатка 3D сход-развала в «зелёной зоне».\n            4. <strong>Контроль моментов затяжки (Torque Check)</strong>: повторная протяжка колёсных гаек/болтов (<code>110–120 Н·м</code>) и болтов подрамника/суппортов тарированным динамометрическим ключом в присутствии комиссии.</p>\n        ",
